//! The utility functions, one module per concern of the style crates.
//!
//! Every function returns a [`Utility`](crate::Utility); the zero-argument
//! ones are generated by [`constants!`].

/// Defines one documented zero-argument utility function per entry.
macro_rules! constants {
    ($($(#[$meta:meta])* $name:ident = $rule:expr;)*) => {
        $(
            $(#[$meta])*
            pub fn $name() -> crate::Utility {
                crate::Utility::from($rule)
            }
        )*
    };
}

mod animation;
mod border;
mod color;
mod display;
mod effects;
mod flex;
mod grid;
mod positioning;
mod shadow;
mod sizing;
mod spacing;
mod typography;

